<?php
declare(strict_types=1);
require_once __DIR__.'/global_brand_v704.php';

function bb570_table_exists(string $table): bool {try{$q=db()->prepare('SHOW TABLES LIKE ?');$q->execute([$table]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;}}
function bb570_tenant_id(): int {return function_exists('tenant_id')?tenant_id():0;}
function bb570_city_id(): int {return function_exists('tenant_city_id')?tenant_city_id():(function_exists('tenant_query_city_id')?tenant_query_city_id():0);}
function bb570_groups(): array {return ['O-','O+','A-','A+','B-','B+','AB-','AB+'];}
function bb570_components(): array {return ['whole_blood'=>'Whole Blood','red_cells'=>'Red Cells','plasma'=>'Plasma','platelets'=>'Platelets'];}
function bb570_enabled(): bool {return !function_exists('setting_bool')||setting_bool('bloodbank_v570_enabled',true);}
function bb570_json($v): string {return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'[]';}
function bb570_slug(string $s): string {$s=trim(mb_strtolower($s));$s=preg_replace('/[^a-z0-9]+/u','-',$s)??'';$s=trim($s,'-');return $s?:'blood-bank';}
function bb570_safe_url(string $u): string {$u=trim($u);if($u==='')return '';if(str_starts_with($u,'/'))return $u;if(filter_var($u,FILTER_VALIDATE_URL)&&preg_match('#^https?://#i',$u))return $u;return '';}
function bb570_staff_role_permissions(string $role): array {$map=[
 'manager'=>['bloodbank.dashboard','bloodbank.banks.manage','bloodbank.donors.manage','bloodbank.inventory.manage','bloodbank.donations.manage','bloodbank.requests.manage','bloodbank.appointments.manage','bloodbank.camps.manage','bloodbank.analytics','bloodbank.settings'],
 'inventory'=>['bloodbank.dashboard','bloodbank.inventory.manage','bloodbank.donations.manage','bloodbank.analytics'],
 'donor_officer'=>['bloodbank.dashboard','bloodbank.donors.manage','bloodbank.donations.manage','bloodbank.appointments.manage','bloodbank.camps.manage'],
 'request_desk'=>['bloodbank.dashboard','bloodbank.requests.manage','bloodbank.inventory.manage','bloodbank.appointments.manage'],
 'camp_coordinator'=>['bloodbank.dashboard','bloodbank.camps.manage','bloodbank.donors.manage','bloodbank.appointments.manage'],
 'viewer'=>['bloodbank.dashboard','bloodbank.analytics']
 ];return $map[$role]??$map['viewer'];}
function bb570_user_staff_rows(int $uid): array {if($uid<1||!bb570_table_exists('blood_bank_staff_v570'))return [];try{$tid=bb570_tenant_id();$sql='SELECT s.*,b.name bank_name FROM blood_bank_staff_v570 s LEFT JOIN blood_banks_v570 b ON b.id=s.bank_id WHERE s.user_id=? AND s.status=1'.($tid>0?' AND s.tenant_id=?':'').' ORDER BY s.id';$q=db()->prepare($sql);$q->execute($tid>0?[$uid,$tid]:[$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_allowed_bank_ids(?array $u=null): ?array {$u=$u?:current_user();if(!$u)return [];if(function_exists('is_super_admin')&&is_super_admin($u))return null;if(function_exists('has_permission')&&(has_permission('bloodbank.banks.manage',$u)||has_permission('bloodbank.settings',$u))){$rows=bb570_user_staff_rows((int)$u['id']);if(!$rows)return null;}else{$rows=bb570_user_staff_rows((int)$u['id']);}
 if(!$rows)return null;$ids=[];foreach($rows as $r){if(empty($r['bank_id']))return null;$ids[]=(int)$r['bank_id'];}return array_values(array_unique($ids));}
function bb570_bank_scope(string $column='b.id',?array $u=null): array {$ids=bb570_allowed_bank_ids($u);if($ids===null)return ['',[]];if(!$ids)return [' AND 1=0',[]];return [' AND '.$column.' IN ('.implode(',',array_fill(0,count($ids),'?')).')',$ids];}
function bb570_can_access_bank(int $bankId,?array $u=null): bool {if($bankId<1)return false;$ids=bb570_allowed_bank_ids($u);return $ids===null||in_array($bankId,$ids,true);}
function bb570_require_bank_access(int $bankId,?array $u=null): void {if(!bb570_can_access_bank($bankId,$u))throw new RuntimeException('This Blood Bank staff account is not assigned to that blood bank.');}
function bb570_banks(bool $public=true,?array $u=null): array {try{$tid=bb570_tenant_id();$where=['1=1'];$pa=[];if($tid>0){$where[]='b.tenant_id=?';$pa[]=$tid;}if($public)$where[]="b.status='active'";if(!$public){[$sc,$sp]=bb570_bank_scope('b.id',$u);if($sc){$where[]=substr($sc,5);$pa=array_merge($pa,$sp);}}$q=db()->prepare('SELECT b.* FROM blood_banks_v570 b WHERE '.implode(' AND ',$where).' ORDER BY b.verified DESC,b.name');$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_bank(int $id): ?array {if($id<1)return null;try{$q=db()->prepare('SELECT * FROM blood_banks_v570 WHERE id=? LIMIT 1');$q->execute([$id]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function bb570_inventory_summary(?int $bankId=null,bool $adminScope=false): array {$out=[];foreach(bb570_groups() as $g)$out[$g]=0;try{$tid=bb570_tenant_id();$sql="SELECT blood_group,COUNT(*) units FROM blood_stock_batches_v570 WHERE stock_status='available' AND screening_status='cleared' AND (expires_at IS NULL OR expires_at>NOW())";$pa=[];if($tid>0){$sql.=' AND tenant_id=?';$pa[]=$tid;}if($bankId){$sql.=' AND bank_id=?';$pa[]=$bankId;}elseif($adminScope){[$sc,$sp]=bb570_bank_scope('bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);}$sql.=' GROUP BY blood_group';$q=db()->prepare($sql);$q->execute($pa);foreach($q->fetchAll()?:[] as $r)$out[(string)$r['blood_group']]=(int)$r['units'];}catch(Throwable $e){}return $out;}
function bb570_inventory_detail(?int $bankId=null,bool $adminScope=false): array {try{$tid=bb570_tenant_id();$sql="SELECT s.*,b.name bank_name,d.donor_id FROM blood_stock_batches_v570 s JOIN blood_banks_v570 b ON b.id=s.bank_id LEFT JOIN blood_donations_v570 d ON d.id=s.donation_id WHERE 1=1";$pa=[];if($tid>0){$sql.=' AND s.tenant_id=?';$pa[]=$tid;}if($bankId){$sql.=' AND s.bank_id=?';$pa[]=$bankId;}elseif($adminScope){[$sc,$sp]=bb570_bank_scope('s.bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);}$sql.=' ORDER BY FIELD(s.stock_status,\'available\',\'reserved\',\'quarantine\',\'issued\',\'discarded\'),s.expires_at IS NULL,s.expires_at,s.id DESC LIMIT 1200';$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_public_requests(int $limit=30): array {try{$tid=bb570_tenant_id();$sql="SELECT r.*,b.name bank_name FROM blood_requests_v570 r LEFT JOIN blood_banks_v570 b ON b.id=r.preferred_bank_id WHERE r.is_public=1 AND r.verification_status='verified' AND r.request_status IN ('pending','matched','partially_fulfilled')";$pa=[];if($tid>0){$sql.=' AND r.tenant_id=?';$pa[]=$tid;}$sql.=' ORDER BY FIELD(r.urgency,\'emergency\',\'urgent\',\'routine\'),r.needed_at IS NULL,r.needed_at,r.id DESC LIMIT '.max(1,min(100,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_admin_requests(int $limit=500): array {try{$tid=bb570_tenant_id();$sql='SELECT r.*,b.name bank_name FROM blood_requests_v570 r LEFT JOIN blood_banks_v570 b ON b.id=r.preferred_bank_id WHERE 1=1';$pa=[];if($tid>0){$sql.=' AND r.tenant_id=?';$pa[]=$tid;}[$sc,$sp]=bb570_bank_scope('r.preferred_bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);$sql.=' ORDER BY r.id DESC LIMIT '.max(1,min(1500,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_donors(int $limit=800): array {try{$tid=bb570_tenant_id();$sql='SELECT d.*,b.name bank_name FROM blood_donors_v570 d LEFT JOIN blood_banks_v570 b ON b.id=d.preferred_bank_id WHERE 1=1';$pa=[];if($tid>0){$sql.=' AND d.tenant_id=?';$pa[]=$tid;}[$sc,$sp]=bb570_bank_scope('d.preferred_bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);$sql.=' ORDER BY d.id DESC LIMIT '.max(1,min(2000,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_appointments(int $limit=500): array {try{$tid=bb570_tenant_id();$sql='SELECT a.*,b.name bank_name FROM blood_donation_appointments_v570 a JOIN blood_banks_v570 b ON b.id=a.bank_id WHERE 1=1';$pa=[];if($tid>0){$sql.=' AND a.tenant_id=?';$pa[]=$tid;}[$sc,$sp]=bb570_bank_scope('a.bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);$sql.=' ORDER BY a.scheduled_at DESC LIMIT '.max(1,min(1500,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_donations(int $limit=500): array {try{$tid=bb570_tenant_id();$sql='SELECT d.*,b.name bank_name,o.full_name donor_name FROM blood_donations_v570 d JOIN blood_banks_v570 b ON b.id=d.bank_id LEFT JOIN blood_donors_v570 o ON o.id=d.donor_id WHERE 1=1';$pa=[];if($tid>0){$sql.=' AND d.tenant_id=?';$pa[]=$tid;}[$sc,$sp]=bb570_bank_scope('d.bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);$sql.=' ORDER BY d.collected_at DESC LIMIT '.max(1,min(1500,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_camp(int $id): ?array {if($id<1)return null;try{$q=db()->prepare('SELECT c.*,b.name bank_name FROM blood_camps_v570 c LEFT JOIN blood_banks_v570 b ON b.id=c.bank_id WHERE c.id=? AND c.tenant_id=? LIMIT 1');$q->execute([$id,bb570_tenant_id()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function bb570_camps(bool $public=true,int $limit=200): array {try{$tid=bb570_tenant_id();$sql='SELECT c.*,b.name bank_name FROM blood_camps_v570 c LEFT JOIN blood_banks_v570 b ON b.id=c.bank_id WHERE 1=1';$pa=[];if($tid>0){$sql.=' AND c.tenant_id=?';$pa[]=$tid;}if($public)$sql.=" AND c.status='published' AND c.starts_at>=DATE_SUB(NOW(),INTERVAL 1 DAY)";else{[$sc,$sp]=bb570_bank_scope('c.bank_id');$sql.=$sc;$pa=array_merge($pa,$sp);}$sql.=' ORDER BY c.featured DESC,c.starts_at LIMIT '.max(1,min(500,$limit));$q=db()->prepare($sql);$q->execute($pa);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bb570_admin_stats(): array {
    $s=['banks'=>0,'donors'=>0,'available'=>0,'requests'=>0,'appointments'=>0,'donations30'=>0,'camps'=>0,'expired_soon'=>0];
    try{
        $tid=bb570_tenant_id();$u=current_user();$ids=bb570_allowed_bank_ids($u);
        $scope=function(string $col) use($ids): array {if($ids===null)return ['',[]];if(!$ids)return [' AND 1=0',[]];return [' AND '.$col.' IN ('.implode(',',array_fill(0,count($ids),'?')).')',$ids];};
        $count=function(string $sql,array $params=[]): int {$q=db()->prepare($sql);$q->execute($params);return (int)$q->fetchColumn();};
        $tenantWhere=$tid>0?' WHERE tenant_id=?':' WHERE 1=1';$tenantParams=$tid>0?[$tid]:[];
        [$sc,$sp]=$scope('id');$s['banks']=$count('SELECT COUNT(*) FROM blood_banks_v570'.$tenantWhere.$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('preferred_bank_id');$s['donors']=$count('SELECT COUNT(*) FROM blood_donors_v570'.$tenantWhere.$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('bank_id');$s['available']=$count("SELECT COUNT(*) FROM blood_stock_batches_v570".$tenantWhere." AND stock_status='available' AND screening_status='cleared' AND (expires_at IS NULL OR expires_at>NOW())".$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('preferred_bank_id');$s['requests']=$count("SELECT COUNT(*) FROM blood_requests_v570".$tenantWhere." AND request_status IN ('pending','matched','partially_fulfilled')".$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('bank_id');$s['appointments']=$count("SELECT COUNT(*) FROM blood_donation_appointments_v570".$tenantWhere." AND status IN ('requested','confirmed') AND scheduled_at>=NOW()".$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('bank_id');$s['donations30']=$count("SELECT COUNT(*) FROM blood_donations_v570".$tenantWhere." AND collected_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)".$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('bank_id');$s['camps']=$count("SELECT COUNT(*) FROM blood_camps_v570".$tenantWhere." AND status='published' AND starts_at>=NOW()".$sc,array_merge($tenantParams,$sp));
        [$sc,$sp]=$scope('bank_id');$s['expired_soon']=$count("SELECT COUNT(*) FROM blood_stock_batches_v570".$tenantWhere." AND stock_status='available' AND expires_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 7 DAY)".$sc,array_merge($tenantParams,$sp));
    }catch(Throwable $e){}
    return $s;
}
function bb570_donor_code(): string {return 'DNR-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));}
function bb570_request_no(): string {return 'BR-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));}
function bb570_donation_no(): string {return 'DON-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));}
function bb570_bag_code(): string {return 'BAG-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8));}
function bb570_validate_group(string $g): string {return in_array($g,bb570_groups(),true)?$g:'';}
function bb570_save_public_donor(array $d,?array $u=null): int {$name=trim((string)($d['full_name']??''));$phone=trim((string)($d['phone']??''));$group=bb570_validate_group((string)($d['blood_group']??''));if($name===''||$phone===''||$group==='')throw new RuntimeException('Name, phone and blood group are required.');if(empty($d['consent']))throw new RuntimeException('Consent is required to register as a donor.');$tid=bb570_tenant_id();$cid=bb570_city_id();$uid=$u?(int)$u['id']:null;$bank=(int)($d['preferred_bank_id']??0)?:null;$q=db()->prepare('INSERT INTO blood_donors_v570(tenant_id,city_id,user_id,preferred_bank_id,donor_code,full_name,phone,email,blood_group,date_of_birth,gender,address,area,emergency_contact_name,emergency_contact_phone,donor_status,screening_status,contact_opt_in,public_registry_opt_in,consent_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([$tid,$cid,$uid,$bank,bb570_donor_code(),$name,$phone,trim((string)($d['email']??''))?:null,$group,($d['date_of_birth']??'')?:null,trim((string)($d['gender']??''))?:null,trim((string)($d['address']??''))?:null,trim((string)($d['area']??''))?:null,trim((string)($d['emergency_contact_name']??''))?:null,trim((string)($d['emergency_contact_phone']??''))?:null,'active','pending',!empty($d['contact_opt_in'])?1:0,!empty($d['public_registry_opt_in'])?1:0,date('Y-m-d H:i:s')]);$id=(int)db()->lastInsertId();bb570_track('donor_registered','donor',$id,$bank);return $id;}
function bb570_save_public_request(array $d,?array $u=null): int {$hospital=trim((string)($d['hospital_name']??''));$name=trim((string)($d['contact_name']??''));$phone=trim((string)($d['contact_phone']??''));$group=bb570_validate_group((string)($d['blood_group']??''));if($hospital===''||$name===''||$phone===''||$group==='')throw new RuntimeException('Hospital, contact, phone and blood group are required.');if(empty($d['consent']))throw new RuntimeException('Consent is required to submit a blood request.');$tid=bb570_tenant_id();$cid=bb570_city_id();$verify=function_exists('setting_bool')&&setting_bool('bloodbank_v570_request_review',true)?'pending':'verified';$q=db()->prepare('INSERT INTO blood_requests_v570(tenant_id,city_id,preferred_bank_id,requester_user_id,request_no,patient_name,hospital_name,hospital_area,blood_group,component,units_needed,urgency,needed_at,contact_name,contact_phone,contact_email,address,latitude,longitude,clinical_note,verification_status,request_status,is_public,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([$tid,$cid,(int)($d['preferred_bank_id']??0)?:null,$u?(int)$u['id']:null,bb570_request_no(),trim((string)($d['patient_name']??''))?:null,$hospital,trim((string)($d['hospital_area']??''))?:null,$group,array_key_exists((string)($d['component']??''),bb570_components())?(string)$d['component']:'red_cells',max(1,min(20,(int)($d['units_needed']??1))),in_array((string)($d['urgency']??''),['routine','urgent','emergency'],true)?(string)$d['urgency']:'urgent',($d['needed_at']??'')?:null,$name,$phone,trim((string)($d['contact_email']??''))?:null,trim((string)($d['address']??''))?:null,($d['latitude']??'')!==''?(float)$d['latitude']:null,($d['longitude']??'')!==''?(float)$d['longitude']:null,trim((string)($d['clinical_note']??''))?:null,$verify,'pending',!empty($d['is_public'])?1:0]);$id=(int)db()->lastInsertId();bb570_track('request_created','request',$id,(int)($d['preferred_bank_id']??0)?:null);return $id;}
function bb570_save_appointment(array $d,?array $u=null): int {$campId=(int)($d['camp_id']??0)?:null;$camp=$campId?bb570_camp($campId):null;$bank=(int)($d['bank_id']??0);if($camp&&!empty($camp['bank_id']))$bank=(int)$camp['bank_id'];$name=trim((string)($d['name']??''));$phone=trim((string)($d['phone']??''));$group=bb570_validate_group((string)($d['blood_group']??''));$when=trim((string)($d['scheduled_at']??''));if(!$bank||$name===''||$phone===''||$group===''||$when==='')throw new RuntimeException('Choose a blood bank, date/time and complete donor details.');if($camp){if(($camp['status']??'')!=='published')throw new RuntimeException('This donation camp is not accepting registrations.');if((int)($camp['capacity']??0)>0&&(int)($camp['registered_count']??0)>=(int)$camp['capacity'])throw new RuntimeException('This donation camp has reached its registration capacity.');}$donorId=(int)($d['donor_id']??0)?:null;db()->beginTransaction();try{$q=db()->prepare("INSERT INTO blood_donation_appointments_v570(tenant_id,bank_id,donor_id,camp_id,user_id,name,phone,blood_group,scheduled_at,source,note,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'requested',NOW(),NOW())");$q->execute([bb570_tenant_id(),$bank,$donorId,$campId,$u?(int)$u['id']:null,$name,$phone,$group,$when,$campId?'camp':'public',trim((string)($d['note']??''))?:null]);$id=(int)db()->lastInsertId();if($campId)db()->prepare('UPDATE blood_camps_v570 SET registered_count=registered_count+1,updated_at=NOW() WHERE id=? AND tenant_id=?')->execute([$campId,bb570_tenant_id()]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}bb570_track('appointment_requested','appointment',$id,$bank,['camp_id'=>$campId]);return $id;}
function bb570_compatibility(string $recipient): array {$m=['O-'=>['O-'],'O+'=>['O-','O+'],'A-'=>['O-','A-'],'A+'=>['O-','O+','A-','A+'],'B-'=>['O-','B-'],'B+'=>['O-','O+','B-','B+'],'AB-'=>['O-','A-','B-','AB-'],'AB+'=>bb570_groups()];return $m[$recipient]??[];}
function bb570_track(string $event,string $entity='',?int $entityId=null,?int $bankId=null,array $meta=[]): void {if(!bb570_table_exists('blood_activity_v570'))return;try{$u=current_user();$raw=(string)($_SERVER['REMOTE_ADDR']??'').(string)($_SERVER['HTTP_USER_AGENT']??'').date('Y-m-d');$hash=hash('sha256',$raw.'|bb570');db()->prepare('INSERT INTO blood_activity_v570(tenant_id,bank_id,user_id,visitor_hash,event_type,entity_type,entity_id,meta_json,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())')->execute([bb570_tenant_id(),$bankId,$u?(int)$u['id']:null,$hash,$event,$entity?:null,$entityId,$meta?bb570_json($meta):null]);}catch(Throwable $e){}}
function bb570_public_header(string $title='Blood Bank',string $desc='Blood donation and request services.'): void {global $config;$brand=function_exists('gb704_brand_name')?gb704_brand_name('ShahkotPK'):(function_exists('tenant_brand')?tenant_brand('site_name','ShahkotPK'):($config['app_name']??'ShahkotPK'));$logo=function_exists('gb704_picture')?gb704_picture('bloodbank',$brand):'';$brandMarkup=$logo!==''?$logo.'<span class="gb704-module-label">Blood Bank</span>':'<span>♥</span><b>'.e($brand).'</b><small>Blood Bank</small>';echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="'.e(csrf_token()).'"><title>'.e($title).' - '.e($brand).'</title><meta name="description" content="'.e($desc).'"><link rel="stylesheet" href="/assets/bloodbank-pro-5.7.0.css?v=570">'.(function_exists('gb704_asset_tag')?gb704_asset_tag():'').'<script defer src="/assets/bloodbank-pro-5.7.0.js?v=570"></script></head><body class="bb570-body"><header class="bb570-top"><div class="bb570-shell bb570-nav"><a class="bb570-brand gb704-brand" href="/">'.$brandMarkup.'</a><nav><a href="/blood-bank.php">Blood Bank</a><a href="/blood-donate.php">Donate Blood</a><a href="/blood-request.php">Request Blood</a><a href="/my-blood.php">My Blood Dashboard</a></nav></div></header>'; }
function bb570_public_footer(): void {echo '<footer class="bb570-footer"><div class="bb570-shell"><div><b>ShahkotPK Blood Bank Pro</b><p>Community donation, inventory and request coordination. Medical eligibility and transfusion compatibility must always be confirmed by qualified blood-bank professionals.</p></div><div><a href="/blood-donate.php">Become a Donor</a><a href="/blood-request.php">Request Blood</a></div></div></footer></body></html>';}
function bb570_mask_phone(string $p): string {$p=preg_replace('/\D+/','',$p)??'';if(strlen($p)<5)return 'Private';return substr($p,0,3).'••••'.substr($p,-2);}
function bb570_my_donor(int $uid): ?array {try{$q=db()->prepare('SELECT * FROM blood_donors_v570 WHERE user_id=? ORDER BY id DESC LIMIT 1');$q->execute([$uid]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function bb570_my_data(int $uid): array {$out=['donor'=>bb570_my_donor($uid),'appointments'=>[],'requests'=>[],'donations'=>[]];try{$q=db()->prepare('SELECT a.*,b.name bank_name FROM blood_donation_appointments_v570 a JOIN blood_banks_v570 b ON b.id=a.bank_id WHERE a.user_id=? ORDER BY a.scheduled_at DESC LIMIT 100');$q->execute([$uid]);$out['appointments']=$q->fetchAll()?:[];$q=db()->prepare('SELECT r.*,b.name bank_name FROM blood_requests_v570 r LEFT JOIN blood_banks_v570 b ON b.id=r.preferred_bank_id WHERE r.requester_user_id=? ORDER BY r.id DESC LIMIT 100');$q->execute([$uid]);$out['requests']=$q->fetchAll()?:[];if($out['donor']){$q=db()->prepare('SELECT d.*,b.name bank_name FROM blood_donations_v570 d JOIN blood_banks_v570 b ON b.id=d.bank_id WHERE d.donor_id=? ORDER BY d.collected_at DESC LIMIT 100');$q->execute([(int)$out['donor']['id']]);$out['donations']=$q->fetchAll()?:[];}}catch(Throwable $e){}return $out;}
